from itertools import product
from sympy import Rational, S, convolution
from sympy.discrete.convolutions import convolution_int

for a, b in [([1, 0], [1, 1]), ([S.One, S.Zero], [S.One, S.One]), ([0, 0], [1, 2])]:
    print(convolution(a, b))

count = 0
for n, m in product(range(1, 5), repeat=2):
    for a, b in product(product((-1, 0, 1), repeat=n), product((-1, 0, 1), repeat=m)):
        expected = [sum(a[i]*b[k-i] for i in range(n) if 0 <= k-i < m) for k in range(n+m-1)]
        assert convolution(a, b) == expected, (a, b)
        count += 1
        for cycle in (1, n+m-1, n+m+1):
            assert convolution(a, b, cycle=cycle) == [sum(expected[i::cycle]) for i in range(cycle)]
assert convolution([Rational(1, 2), 0], [Rational(1, 3), 0]) == [Rational(1, 6), 0, 0]
assert convolution_int([1, 0], [1, 1]) == [1, 1]
print(f'Passed {count} exact convolution cases, cyclic variants, rational padding, and helper compatibility.')
